KG42.register("rules-6faa444889642d91810e8a98",{"id":"11-p2p_mechanisms_evaluation::v141-c-R001","paper":"11-p2p_mechanisms_evaluation","record":{"rule_id":"v141-c-R001","mechanism_id":"v141-a-M01","name":"Demand submission","process_stage":"bidding","market_meaning":"The coordinator must reject requested-energy bids exceeding the prescribed ramping rate, thereby limiting demand-bid updates. Scope: Proposed practical enforcement of ramping-rate step length control in P2P energy bidding. Condition: The proposed enforcement rule is adopted and a bid exceeds the prescribed ramping rate. The coordinator limits demand-bid updates by uniformly randomly selecting participants whose energy bids must remain unchanged for that iteration. Scope: Iterative energy bidding using the bid-count form of step length control. Condition: Bid-count control is adopted; the restriction applies to participants selected for the forbidden-update set at the current iteration. Internal prices motivate updates to Prosumer A's submitted demand schedule to use excess local PV generation from Prosumer B. Scope: Appendix B's illustrated SDR interaction: Prosumer A's heater-demand schedule submitted to the coordinator. Condition: The unequal hourly internal buying prices in the illustrated iterations. Participants must submit their requested-energy quantities as part of the energy bids required at every iteration. Scope: Requested-energy quantities within SDR energy bids. The current requested-energy bid must lie within the previous bid plus or minus the ramping rate times the previous bid's absolute value. The resulting interval is clipped to the bid's lower and upper limits. Scope: Requested-energy bid updates in the iterative simulation's ramping-rate step length control. Condition: The ramping-rate form of step length control is adopted. Only rmp′ × 100% of energy bids may change, and each permitted demand-bid change is also restricted to ± rmp′ × 100%. Scope: Illustrated combined bid-count and ramping-rate step length control. Condition: The combined control with the broader ramping rate rmp′ is adopted. Demand bidding is assumed to be conducted on a day-ahead basis. Scope: SDR bidding in the paper's two GB residential case-study sets, with accurate generation and demand forecasts assumed. Demand-bidding iteration must terminate at the iteration limit, including when bids have not converged. Scope: Demand-bidding iteration under the paper's proposed last-defence mechanism. Condition: The predefined maximum iteration count is reached, whether or not convergence has been achieved.","independence_rationale":"Relations governed by the approved function bidding.demand under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["bidding.demand","coordination.local_operator","pricing.local"],"E":[{"edge_id":"v141-c-R001-E001","source":"coordination.local_operator","target":"bidding.demand","type":"limits","constraint_ids":["v141-c-R001-C001","v141-c-R001-C002"],"evidence_ids":["v141-b-g03-E01","v141-b-g03-E04","v141-b-g03-E11"]},{"edge_id":"v141-c-R001-E002","source":"pricing.local","target":"bidding.demand","type":"links","constraint_ids":["v141-c-R001-C003"],"evidence_ids":["v141-b-g07-ev-14","v141-b-g07-ev-15"]}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"bidding","context_text":"Appendix B's illustrated SDR interaction: Prosumer A's heater-demand schedule submitted to the coordinator. | Demand-bidding iteration under the paper's proposed last-defence mechanism. | Illustrated combined bid-count and ramping-rate step length control. | Iterative energy bidding using the bid-count form of step length control. | Proposed practical enforcement of ramping-rate step length control in P2P energy bidding. | Requested-energy bid updates in the iterative simulation's ramping-rate step length control. | Requested-energy quantities within SDR energy bids. | SDR bidding in the paper's two GB residential case-study sets, with accurate generation and demand forecasts assumed.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g02-e22","v141-b-g03-E01","v141-b-g03-E02","v141-b-g03-E03","v141-b-g03-E04","v141-b-g03-E11","v141-b-g03-E15","v141-b-g04-EV07","v141-b-g07-ev-04","v141-b-g07-ev-14","v141-b-g07-ev-15"]},"x":[{"variable_id":"v141-c-R001-x-e-bid-ramping","symbol":"e_i^{bid}","meaning":"Current iteration's requested-energy bid of a prosumer under ramping-rate step length control; it is the bid decision constrained by Formula (8).","kind":"operational","domain":"Real-valued requested-energy bid at iteration i; source gives clipping limits e^{min} and e^{max} but no further domain.","unit":null,"indices":["i"],"evidence_ids":["v141-b-g02-e22","v141-b-g03-E02"]},{"variable_id":"v141-c-R001-x-e-bid-forbid","symbol":"e_{i,j}^{bid}","meaning":"Current iteration energy bid of prosumer j under the bid-count form of step length control; frozen for j in the forbidden set by Formula (9).","kind":"operational","domain":"Real-valued requested-energy bid for prosumer j at iteration i; source gives no further domain.","unit":null,"indices":["i","j"],"evidence_ids":["v141-b-g03-E01","v141-b-g02-e23"]}],"theta":[{"parameter_id":"v141-c-R001-theta-rmp","symbol":"rmp","meaning":"Ramping rate used in Formula (8); the source states it takes a non-negative value.","value":{"kind":"text","number_value":null,"text_value":"non-negative; value not specified in this rule"},"unit":null,"indices":[],"evidence_ids":["v141-b-g02-e22","v141-b-g03-E02"]},{"parameter_id":"v141-c-R001-theta-prev-bid-ramping","symbol":"e_{i-1}^{bid}","meaning":"Previous iteration's requested-energy bid for the same prosumer, used as the baseline in Formula (8).","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["i-1"],"evidence_ids":["v141-b-g02-e22","v141-b-g03-E02"]},{"parameter_id":"v141-c-R001-theta-prev-bid-forbid","symbol":"e_{i-1,j}^{bid}","meaning":"Previous iteration's energy bid of prosumer j, required to be retained by Formula (9) for prosumers in the forbidden set.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["i-1","j"],"evidence_ids":["v141-b-g03-E01"]},{"parameter_id":"v141-c-R001-theta-e-min","symbol":"e^{min}","meaning":"Minimum limit of the energy bid used to clip the lower bound in Formula (8).","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g02-e22","v141-b-g03-E02"]},{"parameter_id":"v141-c-R001-theta-e-max","symbol":"e^{max}","meaning":"Maximum limit of the energy bid used to clip the upper bound in Formula (8).","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g02-e22","v141-b-g03-E02"]},{"parameter_id":"v141-c-R001-theta-rmp-prime","symbol":"rmp'","meaning":"Broader ramping rate used in the combined step-length-control variant; source says rmp' × 100% of bids may be changed and each permitted change should not exceed ± rmp' × 100%.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g03-E03"]},{"parameter_id":"v141-c-R001-theta-I-max","symbol":"I_{\\max}","meaning":"Pre-defined finite maximum number of iterations in the last-defence mechanism; when reached, demand-bidding iteration terminates whether or not it has converged.","value":{"kind":"text","number_value":null,"text_value":"pre-defined finite number; 200 was used in the evaluated first set of cases (v141-b-g04-EV09), but this rule does not fix a general value"},"unit":null,"indices":[],"evidence_ids":["v141-b-g03-E15","v141-b-g04-EV09"]}],"phi":[{"constraint_id":"v141-c-R001-C001","kind":"logical","role":"core","statement":"The coordinator must reject requested-energy bids exceeding the prescribed ramping rate, thereby limiting demand-bid updates. Scope: Proposed practical enforcement of ramping-rate step length control in P2P energy bidding. Condition: The proposed enforcement rule is adopted and a bid exceeds the prescribed ramping rate.","expression":"\\text{accept}_{\\text{coord}}(e_i^{bid}) \\iff \\max(e_{i-1}^{bid}-\\Delta,\\,e^{min}) \\le e_i^{bid} \\le \\min(e_{i-1}^{bid}+\\Delta,\\,e^{max}),\\quad \\Delta=rmp\\,|e_{i-1}^{bid}|","formalization_origin":"equivalent_translation","template_id":null,"members":["coordination.local_operator","bidding.demand"],"variable_refs":["v141-c-R001-x-e-bid-ramping"],"parameter_refs":["v141-c-R001-theta-rmp","v141-c-R001-theta-prev-bid-ramping","v141-c-R001-theta-e-min","v141-c-R001-theta-e-max"],"evidence_ids":["v141-b-g03-E11","v141-b-g02-e22","v141-b-g03-E02"]},{"constraint_id":"v141-c-R001-C002","kind":"logical","role":"core","statement":"The coordinator limits demand-bid updates by uniformly randomly selecting participants whose energy bids must remain unchanged for that iteration. Scope: Iterative energy bidding using the bid-count form of step length control. Condition: Bid-count control is adopted; the restriction applies to participants selected for the forbidden-update set at the current iteration.","expression":"e_{i,j}^{bid}=e_{i-1,j}^{bid},\\quad \\forall j\\in \\mathcal{PA}^{forbid}\\subset \\mathcal{PA},\\quad |\\mathcal{PA}^{forbid}|\\ \\text{pre-defined}","formalization_origin":"source","template_id":null,"members":["coordination.local_operator","bidding.demand"],"variable_refs":["v141-c-R001-x-e-bid-forbid"],"parameter_refs":["v141-c-R001-theta-prev-bid-forbid"],"evidence_ids":["v141-b-g03-E01","v141-b-g03-E04","v141-b-g02-e23"]},{"constraint_id":"v141-c-R001-C003","kind":"procedural","role":"core","statement":"Internal prices motivate updates to Prosumer A's submitted demand schedule to use excess local PV generation from Prosumer B. Scope: Appendix B's illustrated SDR interaction: Prosumer A's heater-demand schedule submitted to the coordinator. Condition: The unequal hourly internal buying prices in the illustrated iterations.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["pricing.local","bidding.demand"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g07-ev-14","v141-b-g07-ev-15"]},{"constraint_id":"v141-c-R001-C004","kind":"procedural","role":"core","statement":"Participants must submit their requested-energy quantities as part of the energy bids required at every iteration. Scope: Requested-energy quantities within SDR energy bids.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g07-ev-04"]},{"constraint_id":"v141-c-R001-C005","kind":"procedural","role":"core","statement":"The current requested-energy bid must lie within the previous bid plus or minus the ramping rate times the previous bid's absolute value. The resulting interval is clipped to the bid's lower and upper limits. Scope: Requested-energy bid updates in the iterative simulation's ramping-rate step length control. Condition: The ramping-rate form of step length control is adopted.","expression":"\\max(e_{i-1}^{bid}-\\Delta,\\,e^{min}) \\le e_i^{bid} \\le \\min(e_{i-1}^{bid}+\\Delta,\\,e^{max}),\\quad \\Delta=rmp\\,|e_{i-1}^{bid}|","formalization_origin":"source","template_id":null,"members":["bidding.demand"],"variable_refs":["v141-c-R001-x-e-bid-ramping"],"parameter_refs":["v141-c-R001-theta-rmp","v141-c-R001-theta-prev-bid-ramping","v141-c-R001-theta-e-min","v141-c-R001-theta-e-max"],"evidence_ids":["v141-b-g02-e22","v141-b-g03-E02"]},{"constraint_id":"v141-c-R001-C006","kind":"procedural","role":"core","statement":"Only rmp′ × 100% of energy bids may change, and each permitted demand-bid change is also restricted to ± rmp′ × 100%. Scope: Illustrated combined bid-count and ramping-rate step length control. Condition: The combined control with the broader ramping rate rmp′ is adopted.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g03-E03"]},{"constraint_id":"v141-c-R001-C007","kind":"procedural","role":"core","statement":"Demand bidding is assumed to be conducted on a day-ahead basis. Scope: SDR bidding in the paper's two GB residential case-study sets, with accurate generation and demand forecasts assumed.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g04-EV07"]},{"constraint_id":"v141-c-R001-C008","kind":"procedural","role":"core","statement":"Demand-bidding iteration must terminate at the iteration limit, including when bids have not converged. Scope: Demand-bidding iteration under the paper's proposed last-defence mechanism. Condition: The predefined maximum iteration count is reached, whether or not convergence has been achieved.","expression":"\\text{terminate demand-bidding iteration at } i = I_{\\max}\\text{, whether or not convergence has been achieved}","formalization_origin":"source","template_id":null,"members":["bidding.demand"],"variable_refs":[],"parameter_refs":["v141-c-R001-theta-I-max"],"evidence_ids":["v141-b-g03-E15","v141-b-g04-EV09"]}],"pi":[{"evidence_id":"v141-b-g02-e22","location":{"location_id":"src-d485825b0d-p07-c2r4__v141-a-M01-coordination","page":7,"printed_page":null,"section":"3.3.1","anchor_text":"This technique limits the number or ramping rate of the changing 2P energy/price bids to increase th","equation_id":"8","figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"formula"},"source_text":"Taking the energy bidding process in iterative implementation as an example, the step length control can be achieved by requiring each prosumer agent to limit the ramping rate of the bid at each iteration:\n                bid     min        bid             bid       max                     bid      max( e i − 1−Δ,e    ) \\leqslant e i  \\leqslant min( e i − 1 + Δ,e    ) Δ = rmp ·|e i − 1 |       (8) \nwhere i is the index of the current iteration during which the bid decision needs to be made, and rmp represents the ramping rate that takes a non-negative value. Formula (8) can be basically interpreted as follows: the value of the current energy bid, e^{\\mathrm{bid}}_i, should be bounded in a range, [e^{\\mathrm{bid}}_{i−1}−Δ,e^{\\mathrm{bid}}_{i−1}+Δ], which is speciﬁed by the ramping rate and the bid of the previous iteration with Δ = rmp ·|e^{\\mathrm{bid}}_{i−1}|. Besides, if the upper bound speciﬁed in this way exceeds the maximum limit of the energy bid e^{\\max}, it should be reduced to e^{\\max} by having min(e^{\\mathrm{bid}}_{i−1} + Δ,e^{\\max}). Similar operation applies to the case of the lower bound. Formula (8) should act as an additional constraint in the decision-making model (as described by Formula (3)) of each prosumer agent."},{"evidence_id":"v141-b-g03-E01","location":{"location_id":"src-d485825b0d-p08-c1r1__v141-a-M01-coordination","page":8,"printed_page":null,"section":null,"anchor_text":"Y. Zhou et al. bid of the previous iteration with Δ = rmp ·|e ibid− 1 |. Besides, if the upper di bo","equation_id":"9","figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"condition"},"source_text":"The step length control can also be achieved by limiting the number of the bids allowed to be changed at each iteration. That is, e_{i,j}^{bid} = e_{i-1,j}^{bid}, j ∈ 𝓟𝓐^{forbid} ⊂ 𝓟𝓐 (9) where j is the index of prosumer agent. 𝓟𝓐^{forbid} is the set of prosumer agents who are forbidden to change their energy bids at the i th iteration. The number of the elements in 𝓟𝓐^{forbid}, i.e. |𝓟𝓐^{forbid}|, is pre-defined. During simulation, Formula (9) should be added to the decision-making model (as described by Formula (3)) of jth prosumer agent to make it function."},{"evidence_id":"v141-b-g03-E02","location":{"location_id":"src-d485825b0d-p08-c1r1__v141-a-M01-coordination","page":8,"printed_page":null,"section":null,"anchor_text":"Y. Zhou et al. bid of the previous iteration with Δ = rmp ·|e ibid− 1 |. Besides, if the upper di bo","equation_id":"8","figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"condition"},"source_text":"bid of the previous iteration with Δ = rmp ·|e_{i-1}^{bid}|. Besides, if the upper bound specified in this way exceeds the maximum limit of the energy bid e^{max}, it should be reduced to e^{max} by having min(e_{i-1}^{bid} + Δ, e^{max}). Similar operation applies to the case of the lower bound. Formula (8) should act as an additional constraint in the decision-making model (as described by Formula (3)) of each prosumer agent."},{"evidence_id":"v141-b-g03-E03","location":{"location_id":"src-d485825b0d-p08-c1r3__v141-a-M01-coordination","page":8,"printed_page":null,"section":null,"anchor_text":"in vergence performance. The eﬀects of this measure with diﬀerent por- re tions of prosumers forbidd","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"condition"},"source_text":"Note that the two types of step length control patterns are able to be used in a combined way to obtain smaller step limits. That is, one can first limit the number of bids allowed to be changed as described in Formula (9), and then limit the change of the allowable bids by using Formula (8). For example, a broader ramping rate, denoted as rmp′, can be defined, indicating that rmp′ × 100% of the bids are allowed to be changed and the change for each bid should not exceed ± rmp′ × 100%."},{"evidence_id":"v141-b-g03-E04","location":{"location_id":"src-d485825b0d-p08-c1r2__v141-a-M01-coordination","page":8,"printed_page":null,"section":null,"anchor_text":"agents who are forbidden to change their energy bids at the i th itera- p tion. The number of the e","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"unknown"},"source_text":"At each iteration, the elements of 𝓟𝓐^{forbid}, i.e. the prosumers who are forbidden to change their bids, are evenly randomly selected by the coordinator to ensure the fairness among prosumers. The number of prosumers forbidden affects the magnitude of energy and price change in the region at each iteration, thus potentially affecting the convergence performance."},{"evidence_id":"v141-b-g03-E11","location":{"location_id":"src-d485825b0d-p09-c1r2__v141-a-M01-coordination","page":9,"printed_page":null,"section":"3.3.3","anchor_text":"y g ( vergence obtained in this way may be far from the feasible optimum). ti th 3.3.3. Practical im","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-09.png","occurrence_role":"condition"},"source_text":"The first technique, step length control, limits the ramping rate of the bids in the bidding process. In practice, this can be realised by the coordinator through setting bidding rules in the implementation model, as described in Section 3.2.4, in a P2P energy sharing mechanism. For example, the mechanism can achieve this by requiring that the coordinator should reject any bid that exceeds the prescribed ramping rate so that all the prosumers have to obey the ramping rate limit. Therefore, the step length control technique in simulation is able to suggest better bidding rules in the implementation model in practice."},{"evidence_id":"v141-b-g03-E15","location":{"location_id":"src-d485825b0d-p10-c1r2__v141-a-M01-coordination","page":10,"printed_page":null,"section":"3.3.4","anchor_text":"p p p p they achieve that, but not to ﬁgure out how they can achieve that. ca th 3.3.4. Last-defence","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-10.png","occurrence_role":"condition"},"source_text":"The proposed last-defence mechanism is just to end the simulation after a pre-defined finite number of iterations, no matter the convergence is achieved or not. If the simulation ends in that way, the status at the last iteration is used in this paper to calculate the index values for evaluation. It is fair to do so because in practice, the bidding and pricing iteration cannot carry on forever and there is a deadline at which the iteration has to stop and the trading is settled. … In the proposed last-defence mechanism, the maximum number of iterations allowed is an important parameter, and should be chosen to be large enough so that the simulation is not forced to be stopped before it converges. However, there is no way to decide a perfect maximum number of iterations a priori … Therefore, heuristic values are used in this paper."},{"evidence_id":"v141-b-g04-EV07","location":{"location_id":"src-d485825b0d-p14-c1r2__v141-a-M01-coordination","page":14,"printed_page":null,"section":"5.2.1","anchor_text":"pp pp y p customer owned an appliance was a result of the sampling from a given probability distribu","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-14.png","occurrence_role":"condition"},"source_text":"For both sets of cases, within a day, the bidding and pricing process was assumed to be conducted on a day-ahead basis, in which all the generation and demand forecast for each customer were assumed to be accurate. The time step of simulation, Δt , was assumed to be 1 h."},{"evidence_id":"v141-b-g07-ev-04","location":{"location_id":"src-d485825b0d-p26-c2r2__v141-a-M01-bidding","page":26,"printed_page":"1018","section":"A.2.1","anchor_text":"p g y ⎫ ∈ T ⎬⎭ (A18) he decision-making model consisting of Formulas (A1)–(A17). With the energy ell","equation_id":"A18","figure_id":null,"table_id":null,"image_ref":"pages/page-26.png","occurrence_role":"formula"},"source_text":"In the SDR mechanism, prosumers are required to provide energy bids for the coordinator at every iteration. Specifically, based on the results of the decision-making model presented in Section A.1, the energy bid of a prosumer is given by\n\ne^{bid} = \\left\\{ e_t^{bid} \\mid e_t^{bid} = \\left( \\sum_{\\delta \\in \\mathcal{A}_f} x_{\\delta,t}^* \\right) + \\left( \\frac{x_t^{ch*}}{\\eta^{ch}} + x_t^{dis*} \\eta^{dis} \\right) + P_t^{must-run} - P_{PV,t}, t \\in T \\right\\}  (A18)\n\nin which x^* = \\{x_{\\delta,t}^*, x_t^{ch*}, x_t^{dis*}\\}, \\delta \\in \\mathcal{A}_f, t \\in T are the optimal solution of the decision-making model consisting of Formulas (A1)-(A17)."},{"evidence_id":"v141-b-g07-ev-14","location":{"location_id":"src-d485825b0d-p28-c2r3__v141-a-M01-coordination","page":28,"printed_page":"1020","section":"Appendix B","anchor_text":"mes singular because the total electricity cost of Prosumer A is always the same ergence of the simu","equation_id":"B2-B6","figure_id":null,"table_id":null,"image_ref":"pages/page-28.png","occurrence_role":"example"},"source_text":"Assume that the initial schedule of Prosumer A is assumed to be\n\nP_{t=1,iter=0}^{EWH} = 2(\\text{kW}) \\quad \\text{and} \\quad P_{t=2,iter=0}^{EWH} = 4(\\text{kW}),  (B2)\n\nthen at 1st iteration, according to Formulae (A18)-(A23) in Appendix A, the internal buying prices will be\n\np_{t=1,iter=1}^{buying} = 5.03(\\text{pence/kWh}) \\quad \\text{and} \\quad p_{t=2,iter=1}^{buying} = 8.15(\\text{pence/kWh}).  (B3)\n\nDue to the fact that p_{t=1}^{buying} \u003c p_{t=2}^{buying}, according to Formula (B1), Prosumer A will reschedule the heater as\n\nP_{t=1,iter=1}^{EWH} = 4(\\text{kW}) \\quad \\text{and} \\quad P_{t=2,iter=1}^{EWH} = 2(\\text{kW}),  (B4)\n\nand send the schedule to the P2P energy sharing coordinator. Then 2nd iteration begins. The coordinator issues the new internal prices based on the schedule made at 1st iteration, being\n\np_{t=1,iter=2}^{buying} = 8.15(\\text{pence/kWh}) \\quad \\text{and} \\quad p_{t=2,iter=2}^{buying} = 5.03(\\text{pence/kWh}).  (B5)\n\nNow p_{t=1}^{buying} > p_{t=2}^{buying}, so Prosumer A reschedules the heater as\n\nP_{t=1,iter=2}^{EWH} = 2(\\text{kW}) \\quad \\text{and} \\quad P_{t=2,iter=2}^{EWH} = 4(\\text{kW}).  (B6)\n\nNote that the schedule becomes exactly the same as the initial schedule. Therefore, the mode in 1st and 2nd iteration will keep repeating in later iterations, and the simulation will never end (i.e. the simulation diverges), as illustrated in Figs. B1 and B2."},{"evidence_id":"v141-b-g07-ev-15","location":{"location_id":"src-d485825b0d-p29-c1r4__v141-a-M01-coordination","page":29,"printed_page":"1021","section":"Appendix B","anchor_text":"Note that the schedule becomes exactly the same as the initial schedule. The iterations, and the sim","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-29.png","occurrence_role":"definition"},"source_text":"Observing the iterative process of the above example (as showcased by Formulae (B2)-(B6) and illustrated in Figs. B1 and B2), it is seen that actually the SDR mechanism gave the right incentive signal every time (i.e. the internal prices motivated Prosumer A to change the schedule to use excess local PV generation from Prosumer B), but due to the discontinuity of the demand function, Prosumer A over-adjusted its power consumption every time, resulting in the oscillation-like divergence. Considering this fact, it is natural to be proposed to limit the change of power consumption of each prosumer for avoiding divergence. Therefore, now assume that at each iteration, Prosumer A is only allowed to at most make a ± 0.1 kW change to its schedule for each time slot. Also assume that Prosumer A will not change its schedule if no more cost can be saved. Keep all the other settings the same, and then run the simulation again. The results are shown in Figs. B3 and B4.\nFrom Figs. B3 and B4, it can be seen that gradually guided by the internal prices, the simulation converges after 10th iteration. Thanks to the limitation for the allowable power change at each iteration, Prosumer A does not over-adjust its power any longer, so oscillation does not happen and convergence is finally achieved. At the convergence, the power consumption of Prosumer A is completely supplied by the local PV generation of Prosumer B at both hours, resulting in perfect local energy balance and the least electricity cost of the whole P2P energy sharing community."},{"evidence_id":"v141-b-g02-e23","location":{"location_id":"src-d485825b0d-p08-c1r1__v141-a-M01-coordination","page":8,"printed_page":null,"section":"3.3.1","anchor_text":"Y. Zhou et al. bid of the previous iteration with Δ = rmp ·|e ibid− 1 |. Besides, if the upper di bo","equation_id":"9","figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"formula"},"source_text":"The step length control can also be achieved by limiting the number of the bids allowed to be changed at each iteration. That is,\n   e^{\\mathrm{bid}}_{i,j} = e^{\\mathrm{bid}}_{i−1,j}    j \\in \\mathcal{PA}^{\\mathrm{forbid}} \\subset \\mathcal{PA}                                         (9)\nwhere j is the index of prosumer agent. \\mathcal{PA}^{\\mathrm{forbid}} is the set of prosumer agents who are forbidden to change their energy bids at the i th iteration. The number of the elements in \\mathcal{PA}^{\\mathrm{forbid}}, i.e. |\\mathcal{PA}^{\\mathrm{forbid}}|, is pre-deﬁned. During simulation, Formula (9) should be added to the decision-making model (as described by Formula (3)) of jth prosumer agent to make it function. ... At each iteration, the elements of \\mathcal{PA}^{\\mathrm{forbid}}, i.e. the prosumers who are forbidden to change their bids, are evenly randomly selected by the coordinator to ensure the fairness among prosumers."},{"evidence_id":"v141-b-g04-EV09","location":{"location_id":"src-d485825b0d-p14-c1r2__v141-a-M01-coordination","page":14,"printed_page":null,"section":"5.2.1","anchor_text":"pp pp y p customer owned an appliance was a result of the sampling from a given probability distribu","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-14.png","occurrence_role":"condition"},"source_text":"The maximum number of iterations was set as 200 as a part of the last-defence mechanism as discussed in Section 3.3.4."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-bidding","v141-a-M01-coordination","v141-a-M03-bidding"],"extras":{"decision_anchor":"bidding.demand","graph_fact_supports":[[{"evidence_id":"v141-b-g03-E11","quote":"For example, the mechanism can achieve this by requiring that the coordinator should reject any bid that exceeds the prescribed ramping rate so that all the prosumers have to obey the ramping rate limit."}],[{"evidence_id":"v141-b-g03-E04","quote":"At each iteration, the elements of 𝓟𝓐^{forbid}, i.e. the prosumers who are forbidden to change their bids, are evenly randomly selected by the coordinator to ensure the fairness among prosumers."},{"evidence_id":"v141-b-g03-E01","quote":"𝓟𝓐^{forbid} is the set of prosumer agents who are forbidden to change their energy bids at the i th iteration."}],[{"evidence_id":"v141-b-g07-ev-15","quote":"the internal prices motivated Prosumer A to change the schedule to use excess local PV generation from Prosumer B"},{"evidence_id":"v141-b-g07-ev-14","quote":"Due to the fact that p_{t=1}^{buying} \u003c p_{t=2}^{buying}, according to Formula (B1), Prosumer A will reschedule the heater as\n\nP_{t=1,iter=1}^{EWH} = 4(\\text{kW}) \\quad \\text{and} \\quad P_{t=2,iter=1}^{EWH} = 2(\\text{kW}),  (B4)\n\nand send the schedule to the P2P energy sharing coordinator."}],[{"evidence_id":"v141-b-g07-ev-04","quote":"In the SDR mechanism, prosumers are required to provide energy bids for the coordinator at every iteration."}],[{"evidence_id":"v141-b-g02-e22","quote":"Formula (8) can be basically interpreted as follows: the value of the current energy bid, e^{\\mathrm{bid}}_i, should be bounded in a range, [e^{\\mathrm{bid}}_{i−1}−Δ,e^{\\mathrm{bid}}_{i−1}+Δ], which is speciﬁed by the ramping rate and the bid of the previous iteration with Δ = rmp ·|e^{\\mathrm{bid}}_{i−1}|."},{"evidence_id":"v141-b-g03-E02","quote":"Besides, if the upper bound specified in this way exceeds the maximum limit of the energy bid e^{max}, it should be reduced to e^{max} by having min(e_{i-1}^{bid} + Δ, e^{max}). Similar operation applies to the case of the lower bound."}],[{"evidence_id":"v141-b-g03-E03","quote":"For example, a broader ramping rate, denoted as rmp′, can be defined, indicating that rmp′ × 100% of the bids are allowed to be changed and the change for each bid should not exceed ± rmp′ × 100%."}],[{"evidence_id":"v141-b-g04-EV07","quote":"For both sets of cases, within a day, the bidding and pricing process was assumed to be conducted on a day-ahead basis, in which all the generation and demand forecast for each customer were assumed to be accurate."}],[{"evidence_id":"v141-b-g03-E15","quote":"The proposed last-defence mechanism is just to end the simulation after a pre-defined finite number of iterations, no matter the convergence is achieved or not."},{"evidence_id":"v141-b-g03-E15","quote":"in practice, the bidding and pricing iteration cannot carry on forever and there is a deadline at which the iteration has to stop and the trading is settled."}]],"C2_formalization":{"graph_sha256":"3ef848d03e568e3fac93ef561c1f2bb49eb9fdd4cd8f59a059881638dd65c8be","applicability":"formalized","reason":"Core ramping-rate and bid-count constraints are directly transcribed from Formulas (8) and (9), the practical coordinator rejection rule is formalized as an equivalent admissibility predicate, and the last-defence iteration limit is formalized as a termination condition. The internal-price/example, bid-submission, combined-rmp-prime and day-ahead items remain not_formalized because the supplied evidence is procedural or ambiguous. B evidence remains unreviewed and is used only as candidate support, not as independently verified source correctness.","bindings":[{"object_id":"v141-c-R001-x-e-bid-ramping","node_ids":["bidding.demand"],"edge_ids":["v141-c-R001-E001"],"rationale":"The current requested-energy bid is the demand-submission decision constrained by the coordinator's ramping-rate limit recorded on edge v141-c-R001-E001."},{"object_id":"v141-c-R001-x-e-bid-forbid","node_ids":["bidding.demand"],"edge_ids":["v141-c-R001-E001"],"rationale":"The current bid of prosumer j is the demand-submission decision frozen by the coordinator's forbidden-update rule recorded on edge v141-c-R001-E001."},{"object_id":"v141-c-R001-theta-rmp","node_ids":["coordination.local_operator","bidding.demand"],"edge_ids":["v141-c-R001-E001"],"rationale":"rmp parameterizes the coordinator-enforced ramping-rate limit on demand-bid updates."},{"object_id":"v141-c-R001-theta-prev-bid-ramping","node_ids":["bidding.demand"],"edge_ids":[],"rationale":"The previous iteration's bid is the historical baseline of the demand-submission decision in Formula (8)."},{"object_id":"v141-c-R001-theta-prev-bid-forbid","node_ids":["bidding.demand"],"edge_ids":[],"rationale":"The previous iteration's bid of prosumer j is the value retained under the bid-count demand-update freeze."},{"object_id":"v141-c-R001-theta-e-min","node_ids":["bidding.demand"],"edge_ids":[],"rationale":"e^{min} clips the lower bound of the requested-energy bid in the demand-submission constraint."},{"object_id":"v141-c-R001-theta-e-max","node_ids":["bidding.demand"],"edge_ids":[],"rationale":"e^{max} clips the upper bound of the requested-energy bid in the demand-submission constraint."},{"object_id":"v141-c-R001-theta-rmp-prime","node_ids":["bidding.demand"],"edge_ids":[],"rationale":"rmp' parameterizes the broader combined step-length-control variant applied to demand-bid changes."},{"object_id":"v141-c-R001-theta-I-max","node_ids":["coordination.local_operator","bidding.demand"],"edge_ids":["v141-c-R001-E001"],"rationale":"The maximum iteration parameter governs the coordinator's last-defence termination of the demand-bidding iteration."},{"object_id":"v141-c-R001-C001","node_ids":["coordination.local_operator","bidding.demand"],"edge_ids":["v141-c-R001-E001"],"rationale":"Formalizes the coordinator rejection rule as an admissibility predicate on demand-submission bids, matching the graph edge in which the coordinator limits bidding.demand."},{"object_id":"v141-c-R001-C002","node_ids":["coordination.local_operator","bidding.demand"],"edge_ids":["v141-c-R001-E001"],"rationale":"Formalizes the bid-count freeze of selected prosumers' demand bids under the coordinator's limiting relationship to bidding.demand."},{"object_id":"v141-c-R001-C005","node_ids":["bidding.demand"],"edge_ids":[],"rationale":"Formalizes the ramping-rate interval on the requested-energy bid as a constraint on demand submission; no graph edge is needed beyond the bidding.demand member because the source adds this as a prosumer-side decision-model constraint."},{"object_id":"v141-c-R001-C008","node_ids":["bidding.demand","coordination.local_operator"],"edge_ids":["v141-c-R001-E001"],"rationale":"Formalizes last-defence termination of demand-bidding iteration, tying the coordinator's predefined iteration limit to the demand-submission process."}],"revision_requests":[]},"C2_delivery":{"raw_sha256":"f32e947a9f543e33474da8373bf8ce60d26a5bb82cc09dd5cfff6ad7f7b1357d","delivery_payload_sha256":"4b02ad5e59f97692cdec4025691fa6160b571e2ab43b8d0c4be38fbbab7f6552","changes":[{"path":"theta.0.value.kind","before":"unspecified","after":"text","reason":"Variant tag follows supplied value fields; no value, symbol or scientific statement is added, removed or rewritten."}],"scientific_fields_unchanged":true,"request_graph_sha256":"3ef848d03e568e3fac93ef561c1f2bb49eb9fdd4cd8f59a059881638dd65c8be","scientific_correctness_verified":false}},"quarantined_references":[]}});
